import{_ as e,o as n,c as l,a2 as i}from"./chunks/framework.CRkDNIZq.js";const f=JSON.parse('{"title":"Architecture Decision Records (ADR Log)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),s={name:"system-design/decisions.md"};function r(a,t,d,o,g,c){return n(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="architecture-decision-records-adr-log" tabindex="-1">Architecture Decision Records (ADR Log) <a class="header-anchor" href="#architecture-decision-records-adr-log" aria-label="Permalink to &quot;Architecture Decision Records (ADR Log)&quot;">​</a></h1><p>This log records all fundamental design and architecture decisions made in <code>19-usage-billing-engine</code>.</p><hr><table tabindex="0"><thead><tr><th style="text-align:left;">ADR ID</th><th style="text-align:left;">Decision Title</th><th style="text-align:left;">Chosen Option</th><th style="text-align:left;">Alternatives Considered</th><th style="text-align:left;">Deciding Factors</th><th style="text-align:left;">Trade-offs Accepted</th><th style="text-align:left;">Revisit When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ADR-01</strong></td><td style="text-align:left;"><strong>Monetary Unit Representation</strong></td><td style="text-align:left;"><strong>Integer Minor Units (Cents) + Decimal</strong></td><td style="text-align:left;">IEEE 754 Floats, String Math</td><td style="text-align:left;">Elimination of binary floating-point rounding errors</td><td style="text-align:left;">Explicit conversion required when displaying dollars in UI</td><td style="text-align:left;">Multi-currency requiring fractional minor units (e.g. crypto/tokens)</td></tr><tr><td style="text-align:left;"><strong>ADR-02</strong></td><td style="text-align:left;"><strong>Primary Database Engine</strong></td><td style="text-align:left;"><strong>PostgreSQL 16 with Range Partitioning</strong></td><td style="text-align:left;">MongoDB, MySQL, DynamoDB, CockroachDB</td><td style="text-align:left;">Strict ACID guarantees, row-level locking, and native table partitioning</td><td style="text-align:left;">Vertical primary node capacity limits</td><td style="text-align:left;">Ingestion exceeds 50,000 QPS sustainably</td></tr><tr><td style="text-align:left;"><strong>ADR-03</strong></td><td style="text-align:left;"><strong>Architecture Style</strong></td><td style="text-align:left;"><strong>Modular Monolith</strong></td><td style="text-align:left;">Distributed Microservices, Serverless</td><td style="text-align:left;">Single atomic database commit across invoices and double-entry ledger</td><td style="text-align:left;">Ingestion and invoicing share server resources</td><td style="text-align:left;">Telemetry ingestion requires independent auto-scaling clusters</td></tr><tr><td style="text-align:left;"><strong>ADR-04</strong></td><td style="text-align:left;"><strong>Ledger Bookkeeping Paradigm</strong></td><td style="text-align:left;"><strong>Append-Only Double-Entry Journal</strong></td><td style="text-align:left;">Single-Entry Mutable Balances</td><td style="text-align:left;">Complete auditability; debit-credit conservation guarantees</td><td style="text-align:left;">Higher storage growth; balance calculation requires summing entries</td><td style="text-align:left;">Historical entries exceed 500 million rows (requires materialized snapshots)</td></tr><tr><td style="text-align:left;"><strong>ADR-05</strong></td><td style="text-align:left;"><strong>Idempotency Deduplication</strong></td><td style="text-align:left;"><strong>Database Unique Index (<code>ix_tenant_idem</code>)</strong></td><td style="text-align:left;">In-Memory Set, Client Session Tokens</td><td style="text-align:left;">Persistence across server restarts and crashes</td><td style="text-align:left;">Synchronous database write latency on every event</td><td style="text-align:left;">Ingestion latency requirements drop below 5 milliseconds</td></tr><tr><td style="text-align:left;"><strong>ADR-06</strong></td><td style="text-align:left;"><strong>Invoice Sequence Numbering</strong></td><td style="text-align:left;"><strong>Row-Level Lock (<code>SELECT ... FOR UPDATE</code>)</strong></td><td style="text-align:left;">Distributed UUIDs, Unchecked Auto-Increment</td><td style="text-align:left;">Legal fiscal requirement for gapless sequence numbers</td><td style="text-align:left;">Serialized queue under concurrent invoice finalizations</td><td style="text-align:left;">Finalizations exceed 500 invoices per second per tenant</td></tr><tr><td style="text-align:left;"><strong>ADR-07</strong></td><td style="text-align:left;"><strong>Proration Calculation Granularity</strong></td><td style="text-align:left;"><strong>Second-Exact Ratio with <code>ROUND_HALF_UP</code></strong></td><td style="text-align:left;">Day-based ratios, Half-month brackets</td><td style="text-align:left;">Fair billing for mid-cycle upgrades at any hour of day</td><td style="text-align:left;">Slightly higher arithmetic calculation overhead</td><td style="text-align:left;">Never; standard financial practice</td></tr><tr><td style="text-align:left;"><strong>ADR-08</strong></td><td style="text-align:left;"><strong>Audit Log Security &amp; PII</strong></td><td style="text-align:left;"><strong>Recursive Regex Sanitization</strong></td><td style="text-align:left;">Storing Raw Diffs, External KMS field encryption</td><td style="text-align:left;">Prevention of credit card and tax ID leakage into logs</td><td style="text-align:left;">Regex scanning overhead on mutation writes</td><td style="text-align:left;">High-throughput bulk administrative migrations</td></tr><tr><td style="text-align:left;"><strong>ADR-09</strong></td><td style="text-align:left;"><strong>Billing Console Framework</strong></td><td style="text-align:left;"><strong>Vanilla ES6+ JavaScript, HTML5 &amp; CSS</strong></td><td style="text-align:left;">React 18, Vue 3, Next.js</td><td style="text-align:left;">Zero build step complexity, instant load time (&lt;100ms), 10KB bundle size</td><td style="text-align:left;">Manual DOM manipulation instead of reactive component state</td><td style="text-align:left;">Console features expand to complex multi-screen enterprise portal</td></tr><tr><td style="text-align:left;"><strong>ADR-10</strong></td><td style="text-align:left;"><strong>Documentation Toolchain</strong></td><td style="text-align:left;"><strong>VitePress with withMermaid Plugin</strong></td><td style="text-align:left;">Docusaurus, MkDocs, GitBook</td><td style="text-align:left;">Fast Vue.js-style static rendering with pure-black dark theme and Mermaid diagrams</td><td style="text-align:left;">Node.js toolchain required for documentation builds</td><td style="text-align:left;">Never; VitePress provides superior developer documentation experience</td></tr></tbody></table>',4)])])}const x=e(s,[["render",r]]);export{f as __pageData,x as default};
